// W24 run context. Times in Africa/Johannesburg (workflow setting). No PII here.
const now = $now.setZone('Africa/Johannesburg');
const first = $input.first().json || {};
const trigger = first.cleanse_missing !== undefined ? 'daily_retry' : (first.timestamp ? 'monthly' : 'manual');
const endpoint = Boolean($env.NCC_REGISTRY_ENDPOINT);
let mode = String($env.NCC_REGISTRY_MODE || 'csv').toLowerCase();
const notes = [];
if (!['api', 'csv'].includes(mode)) { notes.push('NCC_REGISTRY_MODE invalid, using csv'); mode = 'csv'; }
if (mode === 'api' && !endpoint) { notes.push('NCC_REGISTRY_ENDPOINT not set, using csv'); mode = 'csv'; }
const month = now.toFormat('yyyy-MM');
return [{ json: {
  run_id: 'W24-' + month,
  run_month: month,
  run_started_at: now.toISO(),
  trigger,
  mode,
  include_legacy: String($env.W24_INCLUDE_LEGACY || 'false') === 'true',
  test_mode: String($env.W24_TEST_MODE || 'false') === 'true',
  evidence_dir: $env.W24_EVIDENCE_DIR || '/home/node/compliance/evidence',
  inbox_dir: $env.W24_INBOX_DIR || '/home/node/compliance/inbox',
  notes,
} }];

// One item per registry call (api) or a single routing item (csv / none).
const ctx = $('Set run context').first().json;
const leads = $input.all().map(i => i.json).filter(j => j.lead_id);
if (leads.length === 0) return [{ json: { ...ctx, route: 'none', active_count: 0 } }];
if (ctx.mode !== 'api') return [{ json: { ...ctx, route: 'csv', active_count: leads.length } }];
const size = Number($env.NCC_REGISTRY_BATCH_SIZE || 1000);
const out = [];
for (let i = 0; i < leads.length; i += size) {
  out.push({ json: { route: 'api', run_id: ctx.run_id, batch: out.length + 1,
    numbers: leads.slice(i, i + size).map(l => l.phone_e164) } });
}
return out;

// Map registry answers back to lead hashes. Unknown shape = FAIL (never a silent "0 matches").
const leads = $('Read active leads').all().map(i => i.json).filter(j => j.lead_id);
const byDigits = new Map(leads.map(l => [String(l.phone_e164).replace(/\D/g, ''), l.mobile_hash]));
const blocked = new Set(); let seen = 0;
for (const { json: r } of $input.all()) {
  let numbers;
  if (Array.isArray(r.blocked)) numbers = r.blocked;
  else if (Array.isArray(r.results)) numbers = r.results.filter(x => x.blocked || x.opted_out || x.registered).map(x => x.number || x.msisdn);
  else throw new Error('W24: unrecognised NCC registry response shape (no blocked[] or results[])');
  seen += Array.isArray(r.results) ? r.results.length : numbers.length;
  for (const num of numbers) {
    let d = String(num || '').replace(/\D/g, '');
    if (d.startsWith('00')) d = d.slice(2); else if (d.startsWith('0')) d = '27' + d.slice(1);
    const h = byDigits.get(d); if (h) blocked.add(h);
  }
}
return [{ json: { mechanism: 'api:' + ($env.NCC_REGISTRY_ENDPOINT || '').replace(/^(https?:\/\/[^/]+).*/, '$1'), registry_entries_seen: seen, blocked_hashes: [...blocked] } }];

// Hash every registry number with the suppression rule (E.164 digits, no "+", SHA-256 hex). Raw numbers are dropped here.
// Needs NODE_FUNCTION_ALLOW_BUILTIN=crypto (same setting as W28).
const crypto = require('crypto');
const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length);
const col = rows.length ? (['number', 'msisdn', 'mobile', 'phone', 'cell'].find(c => c in rows[0]) || Object.keys(rows[0])[0]) : null;
const hashes = new Set();
for (const r of rows) {
  let d = String(r[col] || '').replace(/\D/g, '');
  if (d.startsWith('00')) d = d.slice(2); else if (d.startsWith('0')) d = '27' + d.slice(1);
  if (d.length >= 10) hashes.add(crypto.createHash('sha256').update(d, 'utf8').digest('hex'));
}
return [{ json: { mechanism: 'csv:' + $('Set run context').first().json.run_month, registry_entries_seen: rows.length, blocked_hashes: [...hashes] } }];

// Matches = active leads whose hash the registry blocks. Output carries hashes + ids only.
const ctx = $('Set run context').first().json;
const leads = $('Read active leads').all().map(i => i.json).filter(j => j.lead_id);
const inp = $input.all().map(i => i.json);
const blocked = new Set(inp.flatMap(j => j.blocked_hashes || []));
const matches = leads.filter(l => blocked.has(l.mobile_hash))
  .map(({ lead_id, broker_id, brand_id, mobile_hash }) => ({ lead_id, broker_id, brand_id, mobile_hash }));
return [{ json: {
  run_id: ctx.run_id, run_month: ctx.run_month, trigger: ctx.trigger, notes: ctx.notes,
  mechanism: inp[0]?.mechanism || 'none (no active leads)',
  registry_entries_seen: inp.reduce((a, j) => a + (j.registry_entries_seen || 0), 0),
  active_checked: leads.length, match_count: matches.length, matches,
} }];

