-- One suppression list (2.3, register C3). Idempotent: needs unique (mobile_hash, source).
with ins as (
  insert into public.suppression (mobile_hash, source, brand_id, lead_id, added_at)
  select m.mobile_hash, 'ncc_registry', m.brand_id, m.lead_id, now()
  from jsonb_to_recordset($1::jsonb) as m(mobile_hash text, brand_id uuid, lead_id uuid)
  on conflict (mobile_hash, source) do nothing
  returning 1
)
select count(*)::int as registry_rows_inserted from ins;

