const ctx = $('Intersect with active leads').first().json;
return ctx.matches.map(m => ({ json: {
  lead_id: m.lead_id, broker_id: m.broker_id, brand_id: m.brand_id,
  reason: 'ncc_registry', source_workflow: 'W24',
  send_lead_confirmation: false, // never message a registry-blocked number
  notify_broker: true,           // agreement 9.5: broker told within 24 h
  idempotency_key: 'W24-' + ctx.run_month + '-' + m.lead_id,
} }));

const r = $input.all().map(i => i.json);
return [{ json: {
  w15_ok: r.filter(x => x.ok === true).length,
  w15_failed: r.filter(x => x.ok !== true).length,
  schedules_cancelled: r.reduce((a, x) => a + (Number(x.schedules_cancelled) || 0), 0),
  brokers_notified: new Set(r.filter(x => x.broker_notified).map(x => x.broker_id)).size,
} }];

// Monthly evidence (ncc-direct-marketer-pack B4). Counts only in the .md; hashes only in the .csv. No numbers, no names.
const ctx = $('Set run context').first().json;
const run = $('Intersect with active leads').first().json;
const rec = $('Reconcile STOP + objections').first().json;
const cnt = $('Count suppression list').first().json;
let w15 = { w15_ok: 0, w15_failed: 0, schedules_cancelled: 0, brokers_notified: 0 };
try { w15 = $('Collapse W15 results').first().json; } catch (e) { /* no matches this month */ }
const finished = $now.setZone('Africa/Johannesburg');
const red = cnt.blocked_but_contactable > 0 || w15.w15_failed > 0 || w15.w15_ok < run.match_count;
const md = [
  '# W24 compliance cleanse evidence ' + ctx.run_month,
  '',
  'Lead Velocity (Pty) Ltd. Private. Generated by n8n W24. Counts only, no personal information.',
  '',
  '| Item | Value |', '|---|---|',
  '| Run ID | ' + ctx.run_id + ' |',
  '| Trigger | ' + ctx.trigger + ' |',
  '| Started / finished (Africa/Johannesburg) | ' + ctx.run_started_at + ' / ' + finished.toISO() + ' |',
  '| Registry mechanism used | ' + run.mechanism + ' |',
  '| Registry entries seen | ' + run.registry_entries_seen + ' |',
  '| Active leads checked | ' + run.active_checked + ' (legacy included: ' + ctx.include_legacy + '; synthetic run: ' + ctx.test_mode + ') |',
  '| Registry matches (new suppressions) | ' + run.match_count + ' |',
  '| Leads suppressed via W15 (ok / failed) | ' + w15.w15_ok + ' / ' + w15.w15_failed + ' |',
  '| Scheduled messages cancelled | ' + w15.schedules_cancelled + ' |',
  '| Brokers notified | ' + w15.brokers_notified + ' |',
  '| STOP gaps closed / objection gaps closed | ' + rec.stop_gaps_fixed + ' / ' + rec.objection_gaps_fixed + ' |',
  '| Added this month by source | ' + JSON.stringify(cnt.added_this_month) + ' |',
  '| Suppression list total (rows / people) | ' + cnt.suppression_rows + ' / ' + cnt.suppressed_people + ' |',
  '| By source (all time) | ' + JSON.stringify(cnt.by_source) + ' |',
  '| Invariant: blocked but still contactable | ' + cnt.blocked_but_contactable + (cnt.blocked_but_contactable ? ' **RED**' : ' (pass)') + ' |',
  '| Notes / errors | ' + ((ctx.notes || []).join('; ') || 'none') + ' |',
  '| Result | ' + (red ? '**RED: fix and re-run**' : 'PASS, awaiting IO sign-off') + ' |',
  '| IO sign-off | pending (console tap) |',
  '',
].join('\n');
const csv = 'mobile_hash,source,run_id\n' + run.matches.map(m => m.mobile_hash + ',ncc_registry,' + ctx.run_id).join('\n') + '\n';
return [{ json: { md, csv, red, run_month: ctx.run_month, evidence_dir: ctx.evidence_dir,
  evidence_url: 'compliance/evidence/' + ctx.run_month + '.md' } }];

// Registry unavailable / unreadable / unknown shape / evidence write failed. No PII in the alert.
const ctx = $('Set run context').first().json;
const err = $input.first().json.error;
const msg = (err && (err.message || err)) || 'unknown error';
return [{ json: { kind: 'w24_failure', workflow: 'W24', run_id: ctx.run_id, trigger: ctx.trigger, mode: ctx.mode,
  to: ['compliance-qa'], severity: 'amber',
  message: 'W24 cleanse failed (' + ctx.mode + '): ' + String(msg).slice(0, 300) + '. Retries daily 06:00; Jonathan alerted after 3 days.' } }];
